'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=0)=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:d,minimumFractionDigits:d}).format(x);
const money=x=>num(x,0)+' ₴';
const mln=x=>num(x/1e6,2)+' <em>млн ₴</em>';
const signed=x=>(x>=0?'+':'−')+money(Math.abs(x));
const pct=x=>x===null?'—':num(x*100,1)+'%';
const colors=['#6ad3a5','#8eb6a2','#a7b3a3','#c7ad77'];
let demo,rows,options,baseOptions,result,active='overview',imported=false,portfolioName='UA Consumer / демопортфель',registryPage=0;
let filter={segment:'',quality:'',search:''};
let strategyReportURL=null;
const titles={montecarlo:['РОЗПОДІЛИ ТА НЕВИЗНАЧЕНІСТЬ','Моделювання Монте-Карло','Ризик дохідності, повернення вкладень і достатності капіталу.'],risk:['ПОРІВНЯННЯ ПОРТФЕЛІВ','Карта ризику та дохідності','Базова IRR, чутливість NPV до стресу та потреба у капіталі.'],strategy:['ПЛАН РОБОТИ ПІСЛЯ ПРИДБАННЯ','Стратегія на 90 днів','Напрями роботи, бюджет, місткість команди та щотижневі контрольні точки.'],prepurchase:['ДАНІ ДО ДАТИ УГОДИ','Оцінка до купівлі','Навчання на історії → індивідуальна ймовірність → очікувані надходження.'],potential:['СТРУКТУРА СТВОРЕННЯ ВАРТОСТІ','Потенціал вимог','Яка частина портфеля покриває покупку й усі витрати.'],costs:['ПОВНА СОБІВАРТІСТЬ','Витрати стягнення','Бюджет роботи з усім пакетом — навіть без платежів.'],cashflow:['ЛІКВІДНІСТЬ І КАПІТАЛ','Грошовий потік','Календар надходжень, витрат і потреби у фінансуванні.'],overview:['РІШЕННЯ ПРО ПРИДБАННЯ','Оцінка портфеля','Від реєстру вимог — до обґрунтованої ціни покупки.'],register:['ЯКІСТЬ ВХІДНИХ ДАНИХ','Реєстр вимог','Склад портфеля, база оцінки та питання для перевірки.'],scenarios:['СТІЙКІСТЬ ІНВЕСТИЦІЇ','Сценарії та ризики','Як збори, витрати та строки змінюють допустиму ціну.'],monitoring:['КОНТРОЛЬ ПІСЛЯ ПОКУПКИ','Прогноз / факт','Незмінний початковий прогноз і окрема історія результатів.'],method:['ПРОЗОРІ ПРАВИЛА','Методологія оцінки','Кожне припущення має бути видимим і перевірюваним.']};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function error(s){$('#alert').textContent=s;$('#alert').className='error';$('#alert').hidden=!s;}
function cumulative(values){let t=0;return values.map(x=>t+=x);}
function chart(series,{threshold=null,height=235,months=null,startAt=1}={}){
  const w=760,h=height,p={l:59,r:17,t:16,b:34};
  const maxLen=months||Math.max(...series.map(s=>s.values.length));
  const max=Math.max(1,...series.flatMap(s=>s.values),threshold||0)*1.12;
  const min=Math.min(0,...series.flatMap(s=>s.values),threshold||0)*1.12;
  const x=i=>p.l+(i+startAt)/maxLen*(w-p.l-p.r),y=v=>h-p.b-(v-min)/(max-min)*(h-p.t-p.b);
  let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Графік прогнозних та фактичних грошових потоків"><defs><linearGradient id="area-${active}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#74b897" stop-opacity=".24"/><stop offset="100%" stop-color="#74b897" stop-opacity=".02"/></linearGradient></defs>`;
  for(let i=0;i<=4;i++){const val=min+(max-min)*i/4;svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(val)}" y2="${y(val)}" stroke="#2a3630"/><text x="${p.l-10}" y="${y(val)+3}" text-anchor="end">${num(val/1e6,1)}</text>`;}
  svg+=`<text class="axis-label" x="${p.l-12}" y="10" text-anchor="end">млн ₴</text>`;
  if(threshold!==null)svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="#b5a77f" stroke-dasharray="5 5"/>`;
  series.forEach((s,j)=>{const path=s.values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');if(!j)svg+=`<path d="M${p.l},${y(0)} ${s.values.map((v,i)=>`L${x(i)},${y(v)}`).join(' ')} L${x(s.values.length-1)},${y(0)} Z" fill="url(#area-${active})"/>`;svg+=`<path d="${path}" stroke="${s.color}" stroke-width="${j?3:2.7}" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`;if(s.points)s.values.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${s.color}" stroke="white" stroke-width="2"/>`);});
  const ticks=[startAt,...Array.from({length:Math.floor(maxLen/6)},(_,i)=>(i+1)*6)];if(!ticks.includes(maxLen))ticks.push(maxLen);
  ticks.forEach(t=>svg+=`<text x="${x(t-startAt)}" y="${h-9}" text-anchor="middle">${t}</text>`);
  return svg+`<text class="axis-label" x="${w-p.r}" y="${h-23}" text-anchor="end">місяць від придбання</text></svg>`;
}
function metric(label,value,foot,style=''){return `<div class="metric ${style}"><div class="metric-top"><span>${label}</span><span>↗</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function payback(r){return r.payback===null?'не досягається':num(r.payback,1)+' міс.';}
function scenarioOptions(type){const o={...options,multiplier:1,payer_multiplier:1,expense_multiplier:1,delay:0};if(type==='stress')Object.assign(o,{payer_multiplier:.8,expense_multiplier:1.25,delay:3});if(type==='upside')Object.assign(o,{payer_multiplier:1.15,expense_multiplier:.9,delay:0});return o;}

function switchTab(tab){if(!titles[tab])tab='overview';active=tab;document.body.dataset.view=tab;if($('#nav-tools'))$('#nav-tools').open=['register','potential','costs','cashflow','scenarios'].includes(tab);$('#strategy-shortcut').hidden=['strategy','risk','montecarlo'].includes(tab);document.querySelectorAll('.tab-panel').forEach(el=>el.hidden=el.id!=='tab-'+tab);document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));['eyebrow','page-title','page-subtitle'].forEach((id,i)=>$('#'+id).textContent=titles[tab][i]);location.hash=tab;$('#import-button').textContent=tab==='risk'?'↑ Знімки JSON':tab==='strategy'?'↑ Дані плану':tab==='prepurchase'?'↑ Пакет JSON':'↑ Імпорт CSV';updateSource();$('#report-button').disabled=(tab==='montecarlo'&&!mcState.result)||(tab==='prepurchase'&&!preState.loaded)||(tab==='strategy'&&!strategyState.loaded);$('#report-button').textContent=tab==='montecarlo'?'↓ Звіт симуляції':tab==='risk'?'↓ Звіт карти':tab==='strategy'?'↓ Звіт стратегії':tab==='prepurchase'?'↓ Звіт до купівлі':'↓ Інвест. висновок';renderActive();}
function overviewCashChart(r){
  // Visual presentation of existing monthly flows: separate labelled scales.
  const w=800,h=270,p={l:52,r:52,t:22,b:30},n=r.gross.length;
  const monthlyMax=Math.max(1,...r.gross)*1.12,monthlyMin=-Math.max(1,...r.costs)*1.15;
  const balance=r.cash_balance.slice(1);
  const totalMin=Math.min(0,...r.cash_balance)*1.08,totalMax=Math.max(1,...r.cash_balance)*1.12;
  const x=i=>p.l+(i+.5)/n*(w-p.l-p.r),y=v=>h-p.b-(v-monthlyMin)/(monthlyMax-monthlyMin)*(h-p.t-p.b),cy=v=>h-p.b-(v-totalMin)/(totalMax-totalMin)*(h-p.t-p.b);
  const width=Math.max(2,(w-p.l-p.r)/n*.6);
  let svg=`<svg class="chart overview-combo-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Надходження та витрати за місяцями, накопичений баланс після покупки на правій шкалі"><defs><linearGradient id="collection-bars" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#80dfb2"/><stop offset="1" stop-color="#3e8b68"/></linearGradient></defs>`;
  for(let i=0;i<=4;i++){let value=monthlyMin+(monthlyMax-monthlyMin)*i/4,yy=y(value);svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${yy}" y2="${yy}" stroke="#303b33"/><text x="${p.l-9}" y="${yy+4}" text-anchor="end">${num(value/1000)}</text>`;}
  for(let i=0;i<=4;i++){let value=totalMin+(totalMax-totalMin)*i/4;svg+=`<text x="${w-p.r+10}" y="${cy(value)+4}">${num(value/1e6,1)}</text>`;}
  svg+=`<text x="${p.l}" y="12">тис. ₴ · місяць</text><text x="${w-p.r}" y="12" text-anchor="end">млн ₴ · баланс</text><line x1="${p.l}" x2="${w-p.r}" y1="${cy(0)}" y2="${cy(0)}" stroke="#687568" stroke-dasharray="4 5"/>`;
  svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(0)}" y2="${y(0)}" stroke="#4b5c4e"/><text x="${p.l-9}" y="${y(0)+4}" text-anchor="end">0</text><text x="${w-p.r+10}" y="${cy(0)+4}">0</text>`;
  r.gross.forEach((v,i)=>{svg+=`<rect x="${x(i)-width/2}" y="${y(v)}" width="${width}" height="${y(0)-y(v)}" rx="1" fill="url(#collection-bars)"><title>Місяць ${i+1}: надходження ${money(v)}</title></rect><rect x="${x(i)-width*.25}" y="${y(0)}" width="${width*.72}" height="${y(-r.costs[i])-y(0)}" fill="#8e9893" opacity=".8"><title>Витрати ${money(r.costs[i])}</title></rect>`;});
  svg+=`<path d="${balance.map((v,i)=>(i?'L':'M')+x(i)+','+cy(v)).join(' ')}" fill="none" stroke="#e9e7d7" stroke-width="2.6" stroke-linejoin="round"/>`;
  balance.forEach((v,i)=>{if(n<=42||i%2===0)svg+=`<circle cx="${x(i)}" cy="${cy(v)}" r="2.5" fill="#e9e7d7"/>`;});
  [1,6,12,18,24,30,36,n].filter((v,i,a)=>v<=n&&a.indexOf(v)===i).forEach(t=>svg+=`<text x="${x(t-1)}" y="${h-8}" text-anchor="middle">${t}</text>`);
  return svg+'</svg>';
}
function renderOverview(){
  if(!$('#overview-metrics'))$('#tab-overview').innerHTML='<div id="overview-controls"></div><div id="overview-metrics" class="metrics"></div><div id="overview-content"></div><details class="panel valuation-settings" id="valuation-settings"><summary><span>Параметри оцінки<span class="settings-subtitle">Ціна, дохідність, бюджет та строки надходжень</span></span><span class="settings-toggle">Налаштувати ↓</span></summary><div id="params" class="params"></div></details>';
  const r=result,pass=r.npv>=0,stress=NPL.evaluate(rows,scenarioOptions('stress'));
  const currentScenario=options.multiplier===1&&options.payer_multiplier===1&&options.expense_multiplier===1&&options.delay===0?'base':options.multiplier===1&&options.payer_multiplier===.8&&options.expense_multiplier===1.25&&options.delay===3?'stress':options.multiplier===1&&options.payer_multiplier===1.15&&options.expense_multiplier===.9&&options.delay===0?'upside':'custom';
  $('#overview-controls').innerHTML=`<div class="overview-controls"><button class="portfolio-identity" data-goto="register"><b>${esc(portfolioName)}</b><span>⌄</span></button><div class="scenario-switch" role="group" aria-label="Застосувати сценарій"><span>Сценарій</span>${[['stress','Стрес'],['base','Базовий'],['upside','Оптимістичний']].map(([key,label])=>`<button data-scenario="${key}" aria-pressed="${key===currentScenario}">${label}</button>`).join('')}</div><button class="control-horizon" data-action="open-settings">Горизонт <b>${r.net.length} міс.</b><span>⌄</span></button><button class="control-currency" data-action="import" aria-label="Імпорт CSV">UAH <span>↑ CSV</span></button></div>`;
  const icon=paths=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths}</svg>`;
  const card=(label,value,foot,svg,cls='')=>`<div class="metric ${cls}"><span class="overview-metric-icon">${svg}</span><div><div class="metric-top"><span>${label}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div></div>`;
  $('#overview-metrics').innerHTML=card('Ціна придбання',mln(options.price),num(options.price/r.face*100,1)+'% від номіналу',icon('<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v12c0 4 16 4 16 0V5M4 11c0 4 16 4 16 0"/>'))+card('Гранична ціна',mln(r.max_price),`<span class="${pass?'positive-text':'negative-text'}">${pass?'Запас до межі':'Перевищення ціни'} · ${money(Math.abs(r.max_price-options.price))}</span>`,icon('<path d="M3 3h9l9 9-9 9-9-9z"/><circle cx="8" cy="8" r="1"/>'))+card('NPV портфеля',`<span class="${pass?'positive-text':'negative-text'}">${r.npv>=0?'+':'−'}${Math.abs(r.npv)<1e6?num(Math.abs(r.npv)/1000)+' <em>тис. ₴</em>':mln(Math.abs(r.npv))}</span>`,'Після витрат на стягнення',icon('<path d="M4 20V11h4v9m4 0V4h4v16m4 0v-6h-1"/>'))+card('Окупність',r.payback===null?'—':num(r.payback,1)+' <em>міс.</em>',r.payback===null?'Не досягається в межах горизонту':'Стійка · без дисконтування',icon('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>'));
  const segRows=Object.entries(NPL.SEGMENTS).map(([k,s],i)=>{const d=r.segments[k]||{count:0,eligible:0,gross:0};return `<tr><td><span class="dot" style="background:${colors[i]}"></span>${s.label}</td><td class="num">${num(d.count)}</td><td class="num">${money(d.eligible)}</td><td class="num">${pct(d.eligible>0?d.gross/d.eligible:0)}</td><td class="num">${money(d.gross)}</td></tr>`;}).join('');
  $('#overview-content').innerHTML=`<div class="overview-analysis"><div class="panel overview-cash-panel"><div class="panel-heading"><div><h2>Грошовий потік портфеля</h2><p>Прогноз надходжень і витрат за ${r.net.length} місяців</p></div></div><div class="legend"><span><i></i>Надходження</span><span><i class="cost-key"></i>Витрати</span><span><i class="balance-line"></i>Баланс після покупки · права шкала</span></div>${overviewCashChart(r)}<p class="fine chart-disclosure">Баланс враховує ціну та початкові витрати. Повна звірка — <button class="text-button" data-goto="cashflow">у календарі потоків →</button></p></div><aside class="panel investment-decision"><div class="panel-heading"><h2>Інвестиційне рішення</h2></div><div class="decision-status ${pass?'':'negative'}">${pass?'✓ ПОПЕРЕДНЬО ПРИЙНЯТНО':'! ЦІНА ПЕРЕВИЩУЄ МЕЖУ'}</div><p class="decision-copy">${pass?'Ціна нижча за модельну межу. Потрібна перевірка документів.':'Ціна не проходить поточний сценарій. Потрібен перегляд припущень.'}</p><dl class="decision-facts"><div><dt>Номінал портфеля</dt><dd>${num(r.face/1e6,2)} млн ₴</dd></div><div><dt>Договорів</dt><dd>${num(r.count)}</dd></div><div><dt>Витрати, з початковими</dt><dd>${num(r.cost_total/1e6,2)} млн ₴</dd></div><div><dt>Ставка дисконту</dt><dd>${pct(options.annual_return)}</dd></div><div><dt>Розрахункова IRR</dt><dd>${pct(r.irr)}</dd></div></dl><p class="decision-stress-line ${stress.npv>=0?'positive-text':'negative-text'}">Стрес: NPV ${signed(stress.npv)}</p><button class="button secondary" data-action="open-settings">Переглянути припущення →</button></aside></div><div class="overview-secondary"><div class="panel overview-composition"><div class="panel-heading"><h2>Структура бази оцінки</h2></div><div class="balance-bar"><span style="width:${r.eligible/r.face*100}%;background:#4b8e6c"></span><span style="width:${r.excluded/r.face*100}%;background:#d9c693"></span><span style="width:${r.review/r.face*100}%;background:#c6d0c1"></span></div><div class="balance-key"><div><p>У базі моделі</p><strong>${num(r.eligible/r.face*100,1)}%</strong></div><div><p>Задані виключення</p><strong>${num(r.excluded/r.face*100,1)}%</strong></div><div><p>На перевірці</p><strong>${num(r.review/r.face*100,1)}%</strong></div></div><p class="fine">Частки номіналу. Це не класифікація майбутніх платників. <button class="text-button" data-goto="potential">Деталі →</button></p></div><div class="panel next-steps"><div class="panel-heading"><h2>Наступні кроки · 90 днів</h2></div><button data-goto="register"><span class="step-icon">▤</span><span>Перевірка якості даних</span><span class="badge review">Пріоритет</span><b>›</b></button><button data-goto="strategy"><span class="step-icon">◎</span><span>План роботи та бюджет</span><span class="badge">Проєкт</span><b>›</b></button><button data-goto="strategy"><span class="step-icon">◷</span><span>Щотижневий контроль</span><span class="chip">13 тижнів</span><b>›</b></button><p class="fine">Демонстраційний план потребує калібрування на даних компанії.</p></div></div><div class="panel table-panel overview-segments"><div class="panel-heading"><h2>Економіка сегментів</h2><span class="chip">${r.ready_count} договорів у моделі</span></div><div class="table-wrap"><table><thead><tr><th>Сегмент</th><th class="num">Договорів</th><th class="num">База оцінки</th><th class="num">Збори / база</th><th class="num">Валові збори</th></tr></thead><tbody>${segRows}</tbody></table></div><p class="fine">Джерело прогнозу: ${esc(projectSource())}. Модель та припущення потребують перевірки на історії компанії.</p></div>`;
  if(!$('#price'))renderParams();syncParams();
}
function renderParams(){
  const slider=(id,label,min,max,step,left,right,hint='')=>`<div class="range-field"><label class="field-label" for="${id}">${label}<output id="out-${id}"></output></label><input type="range" id="${id}" data-param="${id}" min="${min}" max="${max}" step="${step}"><div class="range-limits"><span>${left}</span><span>${right}</span></div>${hint?`<div class="field-hint">${hint}</div>`:''}</div>`;
  $('#params').innerHTML=`<h2>Параметри рішення</h2><p class="params-intro">Змініть припущення — оцінка оновиться.</p><div class="params-grid"><div><label class="field-label" for="price">Ціна придбання</label><div class="input-wrap"><input id="price" data-param="price" type="number" min="1" step="10000" aria-label="Ціна придбання, гривень"><span>₴</span></div></div><div><label class="field-label" for="startup">Початкові витрати</label><div class="input-wrap"><input id="startup" data-param="startup" type="number" min="0" step="10000" aria-label="Початкові витрати, гривень"><span>₴</span></div></div>${slider('annual_return','Цільова дохідність',0,150,5,'0%','150%','Ефективна річна ставка дисконтування')}${slider('cost_rate','Частка від зборів',0,60,1,'0%','60%')}${slider('multiplier','Сума від платника / опорної',50,150,5,'50%','150%')}${slider('payer_multiplier','Частка платників / опорної',0,150,5,'0%','150%')}${slider('delay','Затримка надходжень',0,12,1,'0 міс.','12 міс.','Зсуває збори й подовжує ненульові періоди регулярних витрат')}</div><div class="param-divider"></div><button class="reset-button" data-action="reset">↺ Відновити опорні параметри</button><p class="param-note">${esc(projectSource())} · прогноз ${result.collection_months} міс.<br>Детальний бюджет — у «Витрати стягнення». Податки та боргове фінансування не включено.</p><div class="stress-preview"><span class="eyebrow">ПЕРЕВІРКА СТІЙКОСТІ</span><strong>−20% платників · +3 місяці</strong><p class="fine">Майбутні витрати зростають на 25%.</p><button class="text-button" data-goto="scenarios">Переглянути сценарії →</button></div>`;
}
const PERCENT_PARAMS=['annual_return','cost_rate','multiplier','payer_multiplier','legal_share','expense_multiplier'];
function syncParams(){document.querySelectorAll('[data-param]').forEach(el=>{const k=el.dataset.param;if(document.activeElement!==el)el.value=PERCENT_PARAMS.includes(k)?Math.round(options[k]*100):options[k];const out=$('#out-'+k);if(out)out.textContent=k==='delay'?options[k]+' міс.':num(options[k]*100,0)+'%';});}

function renderRegister(){
  const r=result,reviewCount=rows.length-r.ready_count;
  $('#tab-register').innerHTML=`<div class="submetrics"><div class="panel submetric"><span>ЗАЯВЛЕНИЙ НОМІНАЛ</span><strong>${num(r.face/1e6,2)} млн ₴</strong><p class="fine">Тіло + проценти + штрафні нарахування</p></div><div class="panel submetric"><span>ДОГОВОРІВ У МОДЕЛІ</span><strong>${num(r.ready_count)}</strong><p class="fine">${num(r.ready_count/r.count*100,1)}% від кількості вимог</p></div><div class="panel submetric"><span>ПОТРЕБУЮТЬ ПЕРЕВІРКИ</span><strong>${num(reviewCount)}</strong><p class="fine">Залишок ${money(r.review)} не оцінюється</p></div></div><div class="notice">${imported?'Імпортована вибірка. Джерело прогнозу вказане у проєкті; модель та припущення потребують калібрування.':'Усі записи синтетичні. Позначки якості й виключення створені для демонстрації перевірок.'} CSV обробляється локально у браузері; дані не відправляються на сервер.</div><div class="panel table-panel"><div class="panel-heading"><div><h2>Реєстр договорів</h2><p>База договору = номінал − задане виключення; записи «review» до оцінки не входять</p></div><button class="button small secondary" data-action="export-register">↓ CSV</button></div><div class="toolbar"><input id="search" type="search" placeholder="Пошук за ID договору / позичальника" value="${esc(filter.search)}" aria-label="Пошук у реєстрі"><select id="segment-filter" aria-label="Фільтр сегмента"><option value="">Усі сегменти</option>${Object.entries(NPL.SEGMENTS).map(([k,s])=>`<option value="${k}" ${filter.segment===k?'selected':''}>${s.label}</option>`).join('')}</select><select id="quality-filter" aria-label="Фільтр якості"><option value="">Усі статуси</option><option value="ready" ${filter.quality==='ready'?'selected':''}>Документи ready</option><option value="review" ${filter.quality==='review'?'selected':''}>На перевірці</option></select></div><div class="table-wrap"><table><thead><tr><th>ID договору</th><th>Сегмент</th><th class="num">Прострочка</th><th class="num">Номінал, ₴</th><th class="num">Виключення, ₴</th><th class="num">База*, ₴</th><th>Статус</th></tr></thead><tbody id="registry-body"></tbody></table></div><div class="pager"><span id="page-info"></span><div><button data-action="prev" aria-label="Попередня сторінка">←</button> <button data-action="next" aria-label="Наступна сторінка">→</button></div></div></div><p class="fine">* Для «review» показано залишок, який ще потребує перевірки та не включений у прогноз.</p>`;renderRegistryRows();
}
function filtered(){return rows.filter(r=>(!filter.segment||r.segment===filter.segment)&&(!filter.quality||r.quality===filter.quality)&&(!filter.search||[r.loan_id,r.borrower_id].some(id=>id.toLowerCase().includes(filter.search.toLowerCase()))));}
function renderRegistryRows(){const a=filtered(),size=25;registryPage=Math.max(0,Math.min(registryPage,Math.ceil(a.length/size)-1));const page=a.slice(registryPage*size,(registryPage+1)*size);$('#registry-body').innerHTML=page.length?page.map(r=>`<tr><td><b>${esc(r.loan_id)}</b><br><small style="color:#8b9a8b">${esc(r.borrower_id)}</small></td><td>${NPL.SEGMENTS[r.segment].label}</td><td class="num">${num(r.dpd)} дн.</td><td class="num">${num(r.principal+r.interest+r.penalty)}</td><td class="num">${num(r.excluded_amount)}</td><td class="num">${num(r.principal+r.interest+r.penalty-r.excluded_amount)}</td><td><span class="badge ${r.quality==='review'?'review':''}">${r.quality==='ready'?'Документи ready':'Документи review'}</span><br><small>Прогноз: ${result.records.find(v=>v.loan_id===r.loan_id)?.estimated?'оцінено':'потрібна перевірка'}</small></td></tr>`).join(''):'<tr><td colspan="7" class="empty">За цими умовами записів немає.</td></tr>';$('#page-info').textContent=a.length?`${registryPage*size+1}–${Math.min(a.length,(registryPage+1)*size)} із ${num(a.length)} записів`:'0 записів';$('[data-action=prev]').disabled=registryPage===0;$('[data-action=next]').disabled=(registryPage+1)*size>=a.length;}
function renderScenarios(){
  const variants=[['base','Опорний','100% частки платників · 100% витрат · без затримки'],['stress','Стресовий','80% частки платників · витрати +25% · затримка 3 міс.'],['upside','Сприятливий','115% частки платників · витрати −10% · без затримки']];
  const cards=variants.map(([key,label,desc])=>{const r=NPL.evaluate(rows,scenarioOptions(key));return `<div class="panel scenario-card ${key}"><h3>${label}<span class="badge ${r.npv<0?'review':''}">${r.npv>=0?'Проходить':'Не проходить'}</span></h3><p>${desc}</p><div class="scenario-price">${num(r.max_price/1e6,2)} <small style="font-size:12px;font-weight:400">млн ₴</small></div><p>Гранична ціна придбання</p><div class="scenario-line"><span>NPV за поточної ціни</span><strong class="${r.npv>=0?'positive-text':'negative-text'}">${signed(r.npv)}</strong></div><div class="scenario-line"><span>IRR, річна</span><strong>${pct(r.irr)}</strong></div><div class="scenario-line"><span>Окупність</span><strong>${payback(r)}</strong></div><button class="button secondary" data-scenario="${key}">Застосувати до оцінки →</button></div>`;}).join('');
  const returns=[.30,.45,.60,.75,.90],levels=[.8,.9,1,1.1,1.2];
  const matrix=levels.map(level=>`<tr><th>${num(level*100)}%</th>${returns.map(ret=>{const r=NPL.evaluate(rows,{...options,payer_multiplier:level,annual_return:ret});return `<td class="${r.npv>=0?'pos':'neg'} ${Math.abs(options.annual_return-ret)<1e-8&&Math.abs(options.payer_multiplier-level)<1e-8?'current':''}">${r.npv>=0?'+':'−'}${num(Math.abs(r.npv)/1e6,2)}</td>`;}).join('')}</tr>`).join('');
  $('#tab-scenarios').innerHTML=`<div class="notice">Сценарії задані для порівняння, ймовірності їм не присвоєно. Ціна покупки ${money(options.price)}, початкові витрати ${money(options.startup)} і цільова дохідність ${pct(options.annual_return)} однакові в усіх трьох сценаріях. Календар базових витрат — з поточного бюджету; множники й затримка наведені на картках. Сума від платника — опорна.</div><div class="scenario-grid">${cards}</div><div class="two-col"><div class="panel"><div class="panel-heading"><div><h2>Чутливість NPV, млн ₴</h2><p>Рядки — множник частки платників; стовпці — цільова річна дохідність</p></div></div><div class="table-wrap"><table class="matrix"><thead><tr><th>Платники ↓ / ставка →</th>${returns.map(v=>`<th>${num(v*100)}%</th>`).join('')}</tr></thead><tbody>${matrix}</tbody></table></div><p class="fine">Ціна, сума від платника, початкові витрати, бюджет і затримка — з поточних налаштувань. Зелений: NPV ≥ 0. Червоний: NPV &lt; 0.</p></div><div class="panel method-block"><h2>Що саме загрожує ціні</h2><ol><li><b>Обсяг зборів.</b> Зниження частки погашення зменшує весь потік.</li><li><b>Строки.</b> Та сама сума, отримана пізніше, має нижчу приведену вартість.</li><li><b>Собівартість.</b> Юридичні та операційні витрати зменшують чистий результат.</li><li><b>Якість вимог.</b> Неперевірені записи консервативно не генерують прогнозних зборів.</li></ol><p>Це сценарний стрес-тест. Його результат не є оцінкою ймовірності збитку.</p></div></div>`;
}
function renderMonitoring(){
  if(imported){$('#tab-monitoring').innerHTML='<div class="panel empty"><h2>Для моніторингу потрібна окрема історія</h2><p style="margin:15px 0">Імпорт CSV містить лише реєстр. Фактичні платежі для нього не завантажено.</p><button class="button secondary" data-action="restore-demo">Відновити демонстраційний приклад</button></div>';return;}
  const original=NPL.evaluate(demo.loans,demo.meta.defaults),forecast=original.gross.slice(0,6),actual=demo.meta.observed_gross;
  const sum=a=>a.reduce((x,y)=>x+y,0),ratio=sum(actual)/sum(forecast),delta=sum(actual)-sum(forecast);
  $('#tab-monitoring').innerHTML=`<div class="notice">Окремий синтетичний приклад перших 6 місяців після умовної покупки. Початковий прогноз зафіксовано на опорних параметрах; зміни повзунків його не переписують. Це не реальна історія компанії.</div><div class="submetrics"><div class="panel submetric"><span>ПОЧАТКОВИЙ ПЛАН ЗБОРІВ · 6 МІС.</span><strong>${num(sum(forecast)/1e6,2)} млн ₴</strong></div><div class="panel submetric"><span>СИНТЕТИЧНИЙ ФАКТ · 6 МІС.</span><strong>${num(sum(actual)/1e6,2)} млн ₴</strong></div><div class="panel submetric"><span>ВИКОНАННЯ ПОЧАТКОВОГО ПЛАНУ</span><strong class="${ratio>=1?'positive-text':'negative-text'}">${pct(ratio)}</strong><p class="fine">Відхилення ${signed(delta)}</p></div></div><div class="panel"><div class="panel-heading"><div><h2>Накопичені валові збори</h2><p>Початковий прогноз і окремо заданий демонстраційний факт</p></div><span class="chip">6 місяців спостереження</span></div><div class="legend"><span><i></i>Початковий прогноз</span><span><i class="actual"></i>Синтетичний факт</span></div>${chart([{values:cumulative(forecast),color:'#6ad3a5'},{values:cumulative(actual),color:'#bf9b4d',points:true}],{months:6,height:235})}</div><div class="panel table-panel" style="margin-top:19px"><div class="panel-heading"><div><h2>Місячна звірка</h2><p>Причини відхилень потребують даних про операції та юридичні події</p></div></div><div class="table-wrap"><table><thead><tr><th>Місяць</th><th class="num">План, ₴</th><th class="num">Факт, ₴</th><th class="num">Відхилення, ₴</th><th class="num">Виконання</th></tr></thead><tbody>${forecast.map((v,i)=>`<tr><td>Місяць ${i+1}</td><td class="num">${num(v)}</td><td class="num">${num(actual[i])}</td><td class="num ${actual[i]>=v?'positive-text':'negative-text'}">${signed(actual[i]-v)}</td><td class="num">${pct(actual[i]/v)}</td></tr>`).join('')}</tbody></table></div></div><p class="fine">За самими сумами платежів не можна встановити причину відхилення. Програма не вигадує пояснень: потрібні дані про стратегію, ресурси, дії та зовнішні події.</p>`;
}
function renderMethod(){
  $('#tab-method').innerHTML=`<div class="notice"><b>Межі.</b> Сценарна модель: частки платників, суми та строки є демонстраційними припущеннями. Машинне навчання і автоматичне застосування правових норм не використовуються. Дані синтетичні.</div><div class="two-col"><div class="panel method-block"><h2>Покупка всього пакета</h2><div class="formula">Гранична ціна = Σ (очікувані збори − всі витрати)<sub>t</sub> / (1 + r)<sup>t/12</sup> − Початкові витрати</div><p>r — ефективна річна цільова дохідність. Ціна покупки і початкові витрати сплачуються в момент 0; інші потоки — наприкінці місяця.</p><ul><li>NPV = гранична ціна − ціна всього пакета.</li><li>Прибуток = всі збори − ціна − всі витрати, без дисконтування.</li><li>Піковий капітал = найбільше від’ємне значення накопиченого балансу, взяте за модулем.</li><li>Окупність показує перетин нуля, після якого баланс до кінця горизонту не стає від’ємним.</li><li>IRR обчислюється лише для потоку з одним переходом знака. При повторних відтоках орієнтир — NPV; одиничний корінь IRR не припускається.</li><li>Податки, залучення і погашення кредитної лінії не моделюються. Це оцінка до податків, без левереджу. Ставка дисконтування не додається повторно як витрата.</li></ul></div><div class="panel method-block"><h2>Платники та надходження</h2><p>Ймовірність платежу — припущення сегмента × множник частки платників, максимум 100%. Умовна сума = база договору × опорна частка погашення при платежі × множник суми, максимум 100% бази.</p><div class="formula">Очікувані збори = P(хоча б один платіж) × сума за умови платежу</div><table><thead><tr><th>Сегмент</th><th class="num">P(платіж)</th><th class="num">Сума / база при платежі</th></tr></thead><tbody>${Object.values(NPL.SEGMENTS).map(x=>`<tr><td>${x.label}</td><td class="num">${pct(x.payer)}</td><td class="num">${pct(x.recovery/x.payer)}</td></tr>`).join('')}</tbody></table><p>Очікувані кількості можуть бути дробовими: це сума ймовірностей договорів, а не відомий список майбутніх платників. Для review і нульової бази збори не прогнозуються.</p><p>Крива обраного горизонту (${result.collection_months} міс.): ваги t × exp(−(t−1)/s), нормовані до 1. s: 5, 8, 4, 6 відповідно до рядків таблиці. Затримка зсуває всі збори, зберігаючи їхню суму.</p></div><div class="panel method-block"><h2>Як враховано витрати</h2><ul><li><b>Детальний режим:</b> комісія від зборів + команда, IT і накладні за задану кількість місяців + супровід усіх договорів + перевірка кожного договору в місяці 1 + внутрішні операції + юридичні витрати + календар інших витрат.</li><li>Затримка подовжує ненульові періоди регулярних витрат. Місяці разових дій не зсуваються. Календар може подовжити горизонт до останньої витрати.</li><li>Множник майбутніх витрат застосовується один раз до кожної майбутньої категорії. Ціна та початкові витрати не змінюються.</li><li><b>Спрощений режим:</b> єдиний відсоток замінює всі майбутні статті, а не додається до них.</li><li>Розподіл прямих витрат між договорами з платежами та без них використовує задані ймовірності. Неперевірені вимоги і спільні витрати показуються окремо.</li><li>PV внесків договорів мінус PV спільних і початкових витрат звіряється з граничною ціною. У внеску немає довільного розподілу ціни покупки.</li></ul><p>Витрати на юридичні дії — бюджетні припущення, не автоматична рекомендація звертатися до суду. Потрібна окрема перевірка застосовності.</p></div><div class="panel method-block"><h2>Дані та український контекст</h2><p>Номінал = тіло + проценти + штрафні нарахування. Задане виключення віднімається від номіналу; залишок review не входить у збори. Це не висновок про правову чинність чи безнадійність.</p><p>У виробничій версії потрібні перевірені правила щодо складу боргу, строків, військових пільг, судового та виконавчого статусу. Непідтверджений статус не означає відсутності обмежень.</p><p>Структурний орієнтир: <a href="https://eur-lex.europa.eu/eli/reg_impl/2023/2083/oj/eng" target="_blank" rel="noopener">шаблони NPL ЄС 2023/2083</a>. Це не готові українські правові правила.</p><p>CSV: UTF-8, роздільник — кома, десятковий знак — крапка. Поля: <code>loan_id, borrower_id, segment, principal, interest, penalty, excluded_amount, dpd, quality</code>. segment: bank_early / bank_late / mfo_early / mfo_late; quality: ready / review. Сегмент задає імпортер, DPD є інформаційним полем.</p><p>Ліміт 50 000 рядків і 20 МБ. Реєстр зберігається лише в пам’яті браузера й не відправляється серверу. Повний проєкт зберігайте кнопкою «Зберегти проєкт» і відновлюйте через «Відкрити дані / проєкт».</p><div class="download-links"><button class="button secondary" data-action="import">↑ Імпорт CSV</button><a class="button secondary" href="demo-register.csv" download>↓ Приклад CSV</a><a class="button secondary" href="demo-source.zip" download>↓ Python + джерела</a><button class="button secondary" data-action="restore-demo">↺ Демопортфель</button></div></div></div>`;
}

function renderActive(){projectSync();({montecarlo:renderMonteCarlo,risk:renderRiskMap,overview:renderOverview,register:renderRegister,prepurchase:renderPrepurchase,strategy:renderStrategy,potential:renderPotential,costs:renderCosts,cashflow:renderCashflow,scenarios:renderScenarios,monitoring:projectMonitoring,method:renderMethod}[active])();projectAfterRender();projectBar();}
function recalc(){result=projectEvaluate(options);options=result.options;renderActive();}
function valuationMemoBody(){const r=result,stress=NPL.evaluate(rows,scenarioOptions('stress'));return `<article class="memo"><div class="memo-label">ДЕМОНСТРАЦІЯ · ${imported?'ІМПОРТОВАНИЙ РЕЄСТР, СЦЕНАРНІ КОЕФІЦІЄНТИ':'СИНТЕТИЧНІ ДАНІ'} · ${new Date().toLocaleDateString('uk-UA')}</div><h2>NPL Investment Lab · рішення про покупку</h2><p><b>${esc(portfolioName)}</b> · ${num(r.count)} договорів · номінал ${money(r.face)}.</p><p class="recommendation ${r.npv<0?'negative':''}"><b>${r.npv>=0?'Ціна проходить поточний сценарій.':'Ціна не проходить поточний сценарій.'}</b> Межа ціни всього пакета — <b>${money(r.max_price)}</b> за цільової річної дохідності ${pct(options.annual_return)}. Ціна покупки — ${money(options.price)}.</p><table><tbody><tr><td>Очікувані договори з платежами / без них*</td><td class="num">${num(r.payers,1)} / ${num(r.nonpayers,1)}</td></tr><tr><td>Всі прогнозні надходження</td><td class="num">${money(r.gross_total)}</td></tr><tr><td>Всі витрати, включно з початковими</td><td class="num">${money(r.cost_total)}</td></tr><tr><td>З них прямі витрати на договори без платежів*</td><td class="num">${money(r.allocation.nonpayers)}</td></tr><tr><td>Прибуток до податків і фінансування</td><td class="num">${money(r.profit)}</td></tr><tr><td>NPV / IRR</td><td class="num">${money(r.npv)} / ${r.irr_status==='nonconventional'?'повторні відтоки: див. NPV':pct(r.irr)}</td></tr><tr><td>Стійка окупність / пікова потреба у коштах</td><td class="num">${payback(r)} / ${money(r.funding_peak)}</td></tr><tr><td>Стрес: гранична ціна / NPV</td><td class="num">${money(stress.max_price)} / ${money(stress.npv)}</td></tr></tbody></table><h3>Припущення та бюджет</h3><p>Частка платників: ${num(options.payer_multiplier*100)}% опорної; сума від платника: ${num(options.multiplier*100)}% опорної. Затримка ${options.delay} міс.; горизонт ${r.net.length} міс. Режим: ${options.cost_mode==='detailed'?'детальний бюджет':'єдина частка витрат'}. Частка від зборів ${pct(options.cost_rate)}, множник майбутніх витрат ${num(options.expense_multiplier*100)}%. Початкові ${money(options.startup)}. Команда/IT/накладні: ${money(r.category_totals.team+r.category_totals.it+r.category_totals.overhead)}; супровід/перевірка/операції: ${money(r.category_totals.accounts+r.category_totals.review+r.category_totals.actions)}; юридичні: ${money(r.category_totals.legal)}; інші: ${money(r.category_totals.extra)}; комісія: ${money(r.category_totals.commission)}.</p><h3>Перевірка стійкості та наступні дії</h3><p>Стрес: 80% опорної частки платників, 125% поточного базового бюджету, затримка 3 міс.; сума від платника опорна. Ціна, початкові витрати та цільова ставка незмінні. ${stress.npv<0?'Ціна не проходить стрес-сценарій.':'Ціна проходить стрес-сценарій.'}</p><p>До покупки: підтвердити документи й склад вимог, відкалібрувати модель на історії України, перевірити бюджет дій та врахувати податки й фінансування. Вимог на перевірці: ${num(r.count-r.ready_count)}.</p><small>* Очікування за поточними ймовірностями договорів; це не відомий список платників. Автор підходу: Sergey Golubev. До податків, без левереджу. Юридична чинність і точність прогнозу не підтверджуються демонстрацією.</small></article>`;}

function memoBody(){return projectReport()+(active==='montecarlo'?mcMemo():active==='risk'?riskMemo():active==='strategy'?strategyMemo():active==='prepurchase'?prepurchaseMemo():valuationMemoBody());}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fullMemo(){return `<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${active==='montecarlo'?'NPL · Монте-Карло':active==='risk'?'NPL · Карта ризику та дохідності':active==='strategy'?'NPL · Стратегія на 90 днів':'NPL · Інвестиційний висновок'}</title><style>body{font:14px/1.65 Arial,sans-serif;color:#193c31;max-width:780px;margin:35px auto;padding:0 24px}h2{font-size:22px}h3{font-size:14px;margin:18px 0 5px}p{margin:11px 0}.memo-label{font-size:10px;background:#f6f0d8;padding:9px}.recommendation{background:#eef5e9;padding:14px;border-left:3px solid #629669}.recommendation.negative{background:#fbefea;border-left-color:#b97357}table{width:100%;border-collapse:collapse;font-size:12px}td{padding:7px 10px;border-bottom:1px solid #e4ebdf}.num{text-align:right}li{font-size:12px}small{font-size:10px;color:#758a77}.mc-chart{display:block;width:100%;height:auto;max-height:260px;margin:18px 0;background:#f4f8f4;break-inside:avoid}.mc-chart text{fill:#365540;font:11px Arial,sans-serif}.mc-grid{stroke:#d9e4da}@page{size:A4;margin:17mm}@media print{body{margin:0;padding:0;font-size:11px}h2{font-size:19px}td{padding:5px 8px}p{margin:7px 0}}</style>${memoBody()}</html>`;}
document.addEventListener('click',e=>{
  if(e.target.closest('[data-open-comparison]')){preState.view='comparison';switchTab('prepurchase');return;}
  const nav=e.target.closest('[data-tab]');if(nav){if(nav.dataset.tab==='prepurchase')preState.view='forecast';switchTab(nav.dataset.tab);return;}
  const goto=e.target.closest('[data-goto]');if(goto){switchTab(goto.dataset.goto);return;}
  const scenario=e.target.closest('[data-scenario]');if(scenario){options=scenarioOptions(scenario.dataset.scenario);switchTab('overview');recalc();syncParams();toast('Сценарій застосовано. Припущення — у блоці «Параметри оцінки».');return;}
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='open-settings'){const el=$('#valuation-settings');el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'});}
  if(action==='export-cashflow')exportCashflow();
  if(action==='rank-order'){potentialOrder=potentialOrder==='desc'?'asc':'desc';renderPotential();}
  if(action==='add-extra'){const label=$('#extra-label').value.trim(),month=Number($('#extra-month').value),amount=Number($('#extra-amount').value);try{if(!$('#extra-month').value||!$('#extra-amount').value)throw Error('Вкажіть місяць і суму.');const next={...options,extra_costs:[...options.extra_costs,{label,month,amount}]};const checked=projectEvaluate(next);options=checked.options;result=checked;error('');renderCosts();toast('Витрату включено в календар один раз.');}catch(err){error('Витрату не додано: '+err.message);}}
  const removal=e.target.closest('[data-remove-extra]');if(removal){const index=Number(removal.dataset.removeExtra);options={...options,extra_costs:options.extra_costs.filter((_,i)=>i!==index)};error('');recalc();}
  if(action==='import')$('#csv-input').click();
  if(action==='reset'){options=structuredClone(baseOptions);error('');$('#report-button').disabled=false;document.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));recalc();syncParams();toast('Опорні параметри відновлено.');}
  if(action==='restore-demo'){rows=demo.loans;options=structuredClone(demo.meta.defaults);baseOptions=structuredClone(options);imported=false;portfolioName='UA Consumer / демопортфель';filter={segment:'',quality:'',search:''};registryPage=0;updateSource();error('');recalc();toast('Синтетичний демопортфель відновлено.');}
  if(action==='prev'){registryPage--;renderRegistryRows();}
  if(action==='next'){registryPage++;renderRegistryRows();}
  if(action==='export-register'){const keys=['loan_id','borrower_id','segment','principal','interest','penalty','excluded_amount','dpd','quality'];const cell=v=>{let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('npl-register.csv','\uFEFF'+[keys.join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Реєстр експортовано.');}
});
document.addEventListener('input',e=>{
  const key=e.target.dataset.param;
  if(key){const val=key==='cost_mode'?e.target.value:e.target.value===''?NaN:Number(e.target.value),next={...options,[key]:PERCENT_PARAMS.includes(key)?val/100:val};try{const checked=projectEvaluate(next);options=checked.options;result=checked;error('');document.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));$('#report-button').disabled=false;renderActive();syncParams();}catch(err){e.target.setAttribute('aria-invalid','true');$('#report-button').disabled=true;error('Перевірте параметр: '+err.message);}return;}
  if(e.target.id==='search'){filter.search=e.target.value;registryPage=0;renderRegistryRows();}
});
document.addEventListener('change',e=>{if(e.target.id==='segment-filter')filter.segment=e.target.value;else if(e.target.id==='quality-filter')filter.quality=e.target.value;else return;registryPage=0;renderRegistryRows();});
function updateSource(){if(rows)$('#nav-count').textContent=num(rows.length);if(project&&result?.project_context)projectBar();}

$('#import-button').addEventListener('click',()=>$(active==='risk'?'#risk-input':active==='strategy'?'#strategy-input':active==='prepurchase'?'#pre-input':'#csv-input').click());
$('#csv-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Файл перевищує 20 МБ.');const parsed=NPL.parseCSV(await file.text());const evaluated=NPL.evaluate(parsed,baseOptions);rows=parsed;options=structuredClone(baseOptions);result=evaluated;imported=true;portfolioName=file.name;registryPage=0;filter={segment:'',quality:'',search:''};error('');updateSource();renderActive();toast('CSV перевірено й завантажено локально.');}catch(err){error('Імпорт не виконано: '+err.message);}finally{e.target.value='';}});
$('#report-button').addEventListener('click',()=>{$('#report-dialog .dialog-actions').hidden=false;$('#report-content').innerHTML=memoBody();const isStrategy=active==='strategy',isMC=active==='montecarlo';$('#download-memo').hidden=isStrategy||isMC;$('#download-mc-report').hidden=!isMC;$('#download-strategy-report').hidden=!isStrategy;if(strategyReportURL){URL.revokeObjectURL(strategyReportURL);strategyReportURL=null;}if(isStrategy||isMC){strategyReportURL=URL.createObjectURL(new Blob([fullMemo()],{type:'text/html;charset=utf-8'}));$(isMC?'#download-mc-report':'#download-strategy-report').href=strategyReportURL;}$('#report-dialog').showModal();});
$('#close-report').addEventListener('click',()=>$('#report-dialog').close());
$('#download-memo').addEventListener('click',()=>{download(active==='montecarlo'?'npl-monte-carlo-report.html':active==='risk'?'npl-risk-map-report.html':active==='strategy'?'npl-strategy-90d.html':'npl-investment-memo.html',fullMemo(),'text/html;charset=utf-8');toast(active==='strategy'?'Звіт стратегії збережено.':'Інвестиційний висновок збережено.');});
$('#print-memo').addEventListener('click',()=>window.print());
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(tab!==active&&titles[tab])switchTab(tab);});
async function init(){try{$('#tab-overview').innerHTML='<div class="panel loadscreen">Підготовка демонстраційного портфеля…</div>';const response=await fetch('demo.json');if(!response.ok)throw Error('Не вдалося отримати демопортфель.');demo=await response.json();rows=demo.loans;options=structuredClone(demo.meta.defaults);baseOptions=structuredClone(options);await projectInitialize();updateSource();switchTab(location.hash.slice(1)||'overview');}catch(err){error(err.message);$('#tab-overview').innerHTML='<div class="panel empty">Оновіть сторінку, щоб повторити завантаження.</div>';}}
init();
